#!/usr/bin/env python3
"""TMR-4/068 exact archived audit-source reconstruction loader.

Runs only standard-library Python. Requires the original TMR-4/062
tmr4_live_core062.py alongside this loader in experiments/tmr/.
The decoded executable SHA256 must match the actually executed audit:
c4a19809895cdb06b0dcc95e4f3c6563b0bb36be70d66287b4573e981fe38408
"""
import base64
import hashlib
import runpy
import zlib
from pathlib import Path

ENCODED = """"""
source = zlib.decompress(base64.b64decode(ENCODED))
expected = "c4a19809895cdb06b0dcc95e4f3c6563b0bb36be70d66287b4573e981fe38408"
actual = hashlib.sha256(source).hexdigest()
if actual != expected:
    raise SystemExit("audit source integrity failure: " + actual)
out = Path(__file__).with_name("tmr4_ladder068.py")
if out.exists() and out.read_bytes() != source:
    raise SystemExit("would overwrite modified local audit source")
out.write_bytes(source)
runpy.run_path(str(out), run_name="__main__")
